import { addDays, addMonths, addWeeks, addYears, format, parseISO } from 'date-fns'
import type { CalendarEvent, Recurrence } from '@/types/domain'

/**
 * Recurrence expansion (CAL-02).
 *
 * Occurrences are computed on demand for the window being displayed and never
 * written to the database. Materialising a "daily forever" event would mean
 * thousands of rows, a slow backup, and a delete that has to hunt them all
 * down; a pure function over the stored rule has none of those problems.
 */

/** Hard ceiling so a mistyped rule cannot lock up the calendar. */
const MAX_OCCURRENCES = 400

export function expand(rule: Recurrence, startISO: string, fromISO: string, toISO: string): string[] {
  const interval = Math.max(1, Math.floor(rule.interval))
  const start = parseISO(startISO)
  const until = rule.until ? parseISO(rule.until) : null
  const to = parseISO(toISO)
  const out: string[] = []

  let cursor = start
  for (let i = 0; i < MAX_OCCURRENCES; i++) {
    const iso = format(cursor, 'yyyy-MM-dd')
    if (cursor > to) break
    if (until && cursor > until) break
    if (iso >= fromISO) out.push(iso)

    cursor =
      rule.freq === 'daily'
        ? addDays(cursor, interval)
        : rule.freq === 'weekly'
          ? addWeeks(cursor, interval)
          : rule.freq === 'monthly'
            ? addMonths(cursor, interval)
            : addYears(cursor, interval)
  }
  return out
}

/** An event as it appears on one specific day. */
export interface Occurrence {
  event: CalendarEvent
  date: string
  /** True for every instance after the first — the stored row keeps its own date. */
  isRepeat: boolean
}

/**
 * Every occurrence of every event inside a window, keyed by date.
 * Non-recurring events pass straight through.
 */
export function occurrencesInRange(
  events: CalendarEvent[],
  fromISO: string,
  toISO: string,
): Map<string, Occurrence[]> {
  const map = new Map<string, Occurrence[]>()
  const push = (date: string, o: Occurrence) => {
    const list = map.get(date)
    if (list) list.push(o)
    else map.set(date, [o])
  }

  for (const event of events) {
    if (!event.recurrence) {
      if (event.date >= fromISO && event.date <= toISO) {
        push(event.date, { event, date: event.date, isRepeat: false })
      }
      continue
    }
    for (const date of expand(event.recurrence, event.date, fromISO, toISO)) {
      push(date, { event, date, isRepeat: date !== event.date })
    }
  }
  return map
}
